syntax:
Comparator<T> comp = (a, b) -> a.length() - b.length();
list.sort(comp);

// أو:
Comparator.comparingInt(T::length)

example:
import java.util.*;

ArrayList<String> names = new ArrayList<>(
    Arrays.asList("سارة", "أحمد", "محمد", " علي")
);

names.sort(Comparator.comparingInt(String::length));
System.out.println(names); // [ علي, سارة, أحمد, محمد]

names.sort(Comparator.comparingInt(String::length).reversed());
System.out.println(names); // [محمد, سارة, أحمد, علي]

